#include <stdio.h>

/* ===== 招牌区 =====
   身子都在下面，可一块招牌都没挂 —— 翻译官喵读到 main 里的使唤就停了。
   在这块空地补两条宣告（收什么、还什么，行尾分号）：
   · fish_scale：收「每碗几条」和「几碗」，还总条数；
   · fish_double：收一只数，还它翻番的数。 */


int main(void) {
    int bag = fish_scale({per}, {times});
    printf("先码 %d 条\n", bag);
    printf("翻番 %d 条\n", fish_double(bag));
    return 0;
}

int fish_scale(int per, int times) {
    return per * times;
}

int fish_double(int n) {
    return n * 2;
}

referenceSolutionTemplate:
#include <stdio.h>

/* ===== 招牌区 ===== */
int fish_scale(int per, int times);
int fish_double(int n);

int main(void) {
    int bag = fish_scale({per}, {times});
    printf("先码 %d 条\n", bag);
    printf("翻番 %d 条\n", fish_double(bag));
    return 0;
}

int fish_scale(int per, int times) {
    return per * times;
}

int fish_double(int n) {
    return n * 2;
}
